-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.92.0',
  '2026-09-19',
  'Пульт ТВ: фон, пропуск заставки, таймер сна, слайд-шоу с музыкой',
  E'Медиатеку на ТВ можно украсить: в админке во вкладке «Оформление» выбирается фон страницы — снимок из «Фото» (стрелками на пульте) или файл с компьютера, — его размытие и затемнение. На экране сериала вместо общего фона — его постер, сильно размытый во всю ширину.\n\nЗаставку и титры отмечают один раз, в любой серии («✂ Заставка и титры» под видео), — дальше на весь сериал: во время заставки появляется «⏭ Пропустить заставку» (или она пропускается сама), на титрах — «Следующая серия через 10 с». Во весь экран OK нажимает эту кнопку, «Назад» — отказывается.\n\n«🌙 Сон» под видео: через 15, 30, 60, 90 минут или после этой серии звук тихо уходит, и всё встаёт на паузу. Во весь экран стрелки вверх-вниз мотают на 5 минут (или меняют громкость — выбирается в «Оформлении»).\n\nВ альбомах фото теперь и ролики с телефона — значок ▶ в полосе, смотрятся прямо в просмотрщике. У альбома — «▶ Слайд-шоу»: снимки по очереди с плавной сменой, каждые 3–12 секунд, по порядку или вперемешку, под музыку из библиотеки — целой папкой по кругу или одной песней по кругу. OK — пауза, «Назад» — выход.\n\nОбложку можно поставить любой папке и фильму — кнопка «🎨» в админке: музыкальным альбомам, альбомам фото, сериалам.',
  E'Агент. looks.go: looks.json в кэше (bg_blur, bg_dim, arrows seek|volume, bg_ver), GET /api/settings и GET /background (app/background.jpg, ссылка с ?v=), POST /api/admin/settings, POST|DELETE /api/admin/image?target=background|cover&id= — тело картинка (image/*, до 30 МБ) или {photo_id} (у ролика берётся его кадр); картинка вписывается (фон 1920×1080, обложка 1000×1000) с поворотом по EXIF через общий decodeFit. Обложка папки — скрытый .cover.jpg внутри (главнее всего в existingPoster; переезжает и удаляется с папкой; в альбоме фото не становится лишним снимком), у файла — «Имя.jpg» рядом (прочие расширения убираются). Постеры музыки и альбомов фото — только свои; posterURL несёт время правки картинки, иначе суточный кэш показывал бы старую обложку.\n\nmarks.go: marks.json, GET/PUT /api/marks — начало и конец заставки от начала серии, титры — от конца (серии разной длины), auto_skip; ключ — ownerOf, как у «Продолжить просмотр», поэтому отметка из любой серии работает на весь сериал. photos.go: ролики (videoExt) — элементы альбома с video/url; превью и «экранная копия» — кадр ffmpeg на 1-й секунде (у коротких — первый), scale с min(), чтобы маленький ролик не растягивался. .mov отдаётся как video/mp4.\n\nСтраница: слой #bg/#bgdim под #app (CSS blur и затемнение; на экране сериала и папки роликов — постер 28px/62%; в плеере и «Файлах» фона нет; постер не загрузился — общий фон). Пропуск: timeupdate сверяет отметки, #skipbox поверх видео и во весь экран; отсчёт титров стоит, пока видео на паузе; по нулю сначала saveProgress(true) (агент переводит «Продолжить» на следующую серию), потом следующая серия. Сон: SLEEP_STEPS, затухание 15 с, затем пауза видео и музыки с возвратом громкости; «Музыка на паузе» при этом молчит; «после серии» — в обработчике ended. Фото во весь экран — два слоя с проявлением и <video> для роликов; слайд-шоу — порядок только из снимков, таймер после каждого шага, музыка через setMusicQueue с временным режимом повтора (all/one), настройки в localStorage. Админка: вкладка «Оформление», экран выбора картинки (альбомы и снимки стрелками, загрузка файла, убрать), «🎨» у строк.\n\nПроверено: looks_test.go (отметки через сезон, сброс, обложка из снимка музыке и альбому, скрытая обложка не в альбоме, удаление обложки, фон из PNG 3000×2000 → 1620×1080, настройки, мусор вместо картинки, ролик в альбоме с кадром), в браузере на локальном агенте с подменой воспроизведения (фоновая вкладка медиа не играет, таймеры спят по минуте): фон из снимка, размытие и затемнение, постер сериала на фоне и отсутствие фона в плеере, обложка музыки на плитке, отметки заставки и титров, пропуск по OK, отказ «Назад», переход после титров с переносом «Продолжить», автопропуск, стрелки ↑↓ (±5 мин и громкость), таймер сна по кругу и «после серии», ролик в альбоме во весь экран и обратно к снимку, слайд-шоу с одной песней по кругу вперемешку — пауза, шаг, выход с возвратом режима повтора.'
);
-- +goose StatementEnd

